package com.safebaba.security;
import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtUtils jwt; private final UserDetailsServiceImpl users; public JwtFilter(JwtUtils jwt,UserDetailsServiceImpl users){this.jwt=jwt;this.users=users;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String token=h.substring(7); if(jwt.valido(token)){String email=jwt.email(token);UserDetails ud=users.loadUserByUsername(email);var auth=new UsernamePasswordAuthenticationToken(ud,null,ud.getAuthorities());auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req));SecurityContextHolder.getContext().setAuthentication(auth);}} chain.doFilter(req,res);} }
